section.script:
var view     = "historytrmx";
var select1  = "domain(sourcename " + level + "),bytes";
var select2  = "domain(destinationname " + level + "),bytes";
var select = [select1, select2];
var sort     = "bytes";
if(typeof(where) == 'undefined') where = "";
var query = Query.topN(view, select, where, interval, sort, n);
query.multiquery = true;
var tables = query.run();
var rpt = Report.current();
rpt.table(tables[0]);
rpt.table(tables[1]);
